"""Build an offline research reader. Standard library only; local Node runs tests."""
from pathlib import Path
import html, json, re, subprocess
ROOT=Path(__file__).resolve().parent

def inline(s):
    s=html.escape(s)
    s=re.sub(r'`([^`]+)`',r'<code>\1</code>',s)
    s=re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',s)
    return s

def markdown(text):
    lines=text.splitlines(); out=[]; i=0
    while i<len(lines):
        s=lines[i].strip()
        if not s: i+=1; continue
        if s.startswith('|'):
            rows=[]
            while i<len(lines) and lines[i].strip().startswith('|'):
                row=lines[i].strip(); i+=1
                if re.fullmatch(r'[|\s:\-]+',row): continue
                rows.append([c.strip() for c in row.strip('|').split('|')])
            out.append('<div class="tablewrap"><table>')
            for j,row in enumerate(rows):
                tag='th' if j==0 else 'td'; out.append('<tr>'+''.join(f'<{tag}>'+inline(c)+f'</{tag}>' for c in row)+'</tr>')
            out.append('</table></div>'); continue
        h=re.match(r'^(#{1,6}) (.+)$',s)
        if h:
            level=min(len(h[1])+1,6); out.append(f'<h{level}>'+inline(h[2])+f'</h{level}>'); i+=1; continue
        if s.startswith('- '):
            items=[]
            while i<len(lines) and lines[i].strip().startswith('- '):
                items.append('<li>'+inline(lines[i].strip()[2:])+'</li>'); i+=1
            out.append('<ul>'+''.join(items)+'</ul>'); continue
        para=[s]; i+=1
        while i<len(lines) and lines[i].strip() and not re.match(r'^(#|\||- )',lines[i].strip()):
            para.append(lines[i].strip()); i+=1
        out.append('<p>'+inline(' '.join(para))+'</p>')
    return '\n'.join(out)

run=subprocess.run(['node','--test',str(ROOT/'reference.test.mjs')],capture_output=True,text=True)
(ROOT/'test-results.txt').write_text(run.stdout+run.stderr)
if run.returncode: raise SystemExit('Reference tests failed. See test-results.txt.')
passed=int(re.search(r'^# pass (\d+)',run.stdout,re.M)[1])
pack=json.loads((ROOT/'evidence.json').read_text())
parts=re.split(r'^## ',(ROOT/'RESEARCH.md').read_text(),flags=re.M)[1:]
assert len(parts)==10
