views['4']=lab+views['4']
inputs=[('tasks','Monthly research tasks',12),('nativeMinutes','Native minutes / task',60),('toolMinutes','Tool minutes / task',30),('hourlyValue','Internal hourly value',300),('monthlyFee','Monthly tool fee',1000),('monthlyQaCost','Monthly QA cost',200),('setupCost','One-off setup cost',600),('amortisationMonths','Setup amortisation months',3)]
views['9']='<div class="lab"><div class="eyebrow">CAPACITY VALUE · NOT GUARANTEED CASH SAVINGS</div><h3>Does a tool save useful effort?</h3><p>All amounts below are hypothetical ZAR assumptions, not vendor prices or an approved purchase.</p><div class="fields">'+''.join(f'<label>{label}<input id="{key}" type="number" min="0" value="{value}" step="any"></label>' for key,label,value in inputs)+'</div><div id="valueOutput" aria-live="polite"></div></div>'+views['9']
source_html=[]
for s in pack['sources']:
    source_html.append('<article class="source" data-coverage="'+s['coverage']+'"><div class="eyebrow">'+s['id']+' · '+html.escape(s['publisher'])+'</div><h3>'+html.escape(s['title'])+'</h3><span class="pill">'+s['coverage'].replace('_',' ')+'</span><p>'+html.escape(s['finding'])+'</p><p class="muted">'+html.escape(s['limitation'])+'</p><p class="tiny">Accessed '+s['accessedAt']+' · Page date '+html.escape(s['pageDate'] or 'not stated')+' · Needs review</p><a target="_blank" rel="noopener noreferrer" href="'+html.escape(s['url'],quote=True)+'">Open source ↗</a></article>')
views['sources']='<h2>Source ledger</h2><p>Primary documentation and vendor statements are not interchangeable with independently verified performance. Read coverage is explicit; no knowledge was activated.</p><div class="fields"><label>Search<input id="sourceSearch" placeholder="Publisher, topic or source ID"></label><label>Read coverage<select id="sourceFilter"><option value="all">All sources</option><option value="full_page_text">Full page text</option><option value="selected_sections">Selected sections</option><option value="indexed_excerpt_only">Indexed excerpt only</option><option value="interface_shell_only">Interface shell only</option><option value="page_text_price_unavailable">Price unavailable</option></select></label></div><div class="sourcegrid">'+''.join(source_html)+'</div><h3>Review candidates</h3>'+''.join('<p><strong>'+html.escape(c['title'])+'</strong><br><span class="muted">'+', '.join(c['sourceIds'])+' · '+c['evidenceLabel']+' · needs review</span></p>' for c in pack['candidates'])
css='''*{box-sizing:border-box}body{margin:0;background:#0c141c;color:#edf4f5;font:15px/1.7 system-ui,-apple-system,Segoe UI,sans-serif}a{color:#78dfc9;overflow-wrap:anywhere}button,input,select{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #87eed2;outline-offset:3px}.side{position:fixed;inset:0 auto 0 0;width:236px;padding:27px 18px;background:#111f28;border-right:1px solid #2d414b}.brand{font-size:34px;font-weight:850;letter-spacing:-2px}.brand small{display:block;font-size:10px;letter-spacing:1.5px;font-weight:650;color:#94b4ba}.nav{display:grid;gap:4px;margin-top:27px}.nav button{text-align:left;background:none;border:0;color:#9db6bf;border-radius:7px;padding:9px 12px;font-size:12px}.nav button[aria-current=true]{background:#19413b;color:#95f0d8;font-weight:750}.sidefooter{font-size:10px;color:#82a0ad;margin-top:28px}.main{margin-left:236px;padding:42px 55px 70px;max-width:1530px}.eyebrow{font-size:10px;color:#6fd7be;letter-spacing:1.8px;font-weight:750}.hero{border-bottom:1px solid #30434e;padding:12px 0 35px}.hero h1{font-size:clamp(35px,4.6vw,64px);line-height:1.1;letter-spacing:-2.6px;margin:20px 0}.hero p{font-size:18px;color:#aec4ce;max-width:800px}.notice{background:#162c34;border-left:3px solid #71d6bd;padding:13px 17px;font-size:12px;color:#bacfd6;margin-top:24px}.stats{display:flex;gap:44px;margin:28px 0 0}.stats strong{display:block;font-size:28px;line-height:1.2}.stats span{font-size:11px;color:#8facb7}.view{padding-top:30px;max-width:1110px}.view[hidden]{display:none}.view h2{font-size:29px;letter-spacing:-.7px}.view h3{font-size:24px;line-height:1.35;letter-spacing:-.4px;margin:32px 0 13px}.view h4{font-size:18px;line-height:1.4;color:#daefeb;margin-top:28px}.view p,.view li{color:#b7cbd4}.view strong{color:#eef6f7}.view li{margin-bottom:9px}.view code{font-size:12px;padding:2px 4px;border-radius:4px;background:#203440;color:#c7ebdf;overflow-wrap:anywhere}.tablewrap{overflow:auto;border:1px solid #344852;border-radius:8px;margin:23px 0}table{border-collapse:collapse;width:100%;font-size:12px;min-width:640px}th,td{text-align:left;vertical-align:top;padding:14px;border-bottom:1px solid #2d414b}th{background:#1a333a;color:#bbebde}td{color:#bdcfd7}.lab{padding:24px;border:1px solid #3c7867;border-radius:13px;background:linear-gradient(120deg,#15392f,#172933);margin:8px 0 36px}.lab h3{margin:10px 0 16px;font-size:26px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin:20px 0}label{display:grid;gap:6px;font-size:11px;color:#b1d2d4;min-width:0}input,select{width:100%;min-width:0;background:#0d2027;color:#edf7f5;border:1px solid #406259;border-radius:6px;padding:10px}.output{border:1px solid #496b66;padding:17px;border-radius:8px;background:#12272b}.output b{font-size:22px;color:#c4f5e6}.output p{margin:5px 0;font-size:13px}.output ul{font-size:12px;margin:10px 0 0;padding-left:20px}.fail{border-color:#b0975e;color:#f0d99e}.pill{display:inline-block;font-size:10px;padding:4px 7px;border:1px solid #3c5d60;border-radius:5px;color:#a9d4d0}.sourcegrid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.source{padding:21px;border:1px solid #2c4754;background:#13252e;border-radius:9px;min-width:0}.source[hidden]{display:none}.source h3{font-size:17px;margin:8px 0 12px}.source p,.source a{font-size:12px}.muted{color:#89a6b2!important}.tiny{font-size:10px!important}.footer{border-top:1px solid #2a414d;margin-top:45px;padding-top:20px;font-size:11px;color:#84a2af}@media(max-width:1000px){.main{padding:30px;margin-left:200px}.side{width:200px}.stats{gap:22px}}@media(max-width:700px){.side{position:static;width:auto;padding:18px;border-right:0}.brand{font-size:27px}.brand small{display:inline;margin-left:17px;font-size:9px}.nav{display:flex;overflow:auto;margin-top:17px}.nav button{white-space:nowrap;font-size:11px}.sidefooter{display:none}.main{margin:0;padding:20px}.hero h1{font-size:39px;letter-spacing:-1.6px}.hero p{font-size:15px}.stats{display:grid;grid-template-columns:1fr 1fr;gap:15px}.fields,.sourcegrid{grid-template-columns:1fr}.lab{padding:18px}.view h3{font-size:23px}}@media print{body{background:white;color:black}.side,.hero,.fields,.lab{display:none}.main{margin:0;padding:0}.view,.view[hidden]{display:block;break-before:page}.view p,.view li,.view strong,td,th{color:black}.source{break-inside:avoid}.tablewrap{overflow:visible}table{min-width:0}}'''
logic=(ROOT/'reference.mjs').read_text().replace('export function','function')
js=r'''
const explanations={ESTIMATE_NOT_ACCOUNTING_OR_AD_ATTRIBUTION:'Vendor estimate: not verified accounting or ad-attributed revenue.',PUBLISHER_REPORT_NOT_INDEPENDENT_CAUSAL_PROOF:'Publisher report: preserve its attribution and independent-verification limitations.',DO_NOT_INVENT_UNSEEN_VIDEO_OR_AUDIO:'Partial review: do not invent unseen shots, audio or timing.',PRESENCE_OR_AGE_DOES_NOT_PROVE_PROFIT:'Activity or longevity: reason to investigate, not proof of profit.',STOPPED_OR_MISSING_DOES_NOT_PROVE_FAILURE:'Stopped or absent: not proof that the creative failed.',RELATIVE_METRIC_NOT_CONVERSION_RATE:'Relative metrics: not an actual conversion rate or purchase count.',HYPOTHESIS_NOT_OBSERVATION:'Inference: a proposed explanation, not an observation.',SAMPLE_IS_NOT_MARKET_EVIDENCE:'Sample data must not enter market evidence.',CONTENT_NOT_INSPECTED:'Content could not be inspected.'};
function evidenceLab(){const active=document.getElementById('activity').value;const r=assessReference({provider:'demo',nativeAdId:'demo-ad',advertiserId:'demo-brand',familyId:'demo-family',sourceUrl:'https://example.invalid/reference',scope:'shared',clientId:null,observedAt:'2026-09-19',validUntil:'2026-10-19',basis:document.getElementById('basis').value,coverage:document.getElementById('coverage').value,reviewStatus:'active',active:active==='unknown'?null:active==='true',metricUnit:document.getElementById('metric').value},{clientId:'demo-client',today:'2026-09-19'});const parent=document.getElementById('evidenceOutput');parent.replaceChildren();const box=document.createElement('div');box.className='output';const b=document.createElement('b');b.textContent='Business profitability: not established';const p=document.createElement('p');p.textContent=r.issues.length?'This simulated record cannot enter reviewed pattern evidence.':'A reviewed record with this structure could inform a hypothesis, never a guaranteed winner.';const ul=document.createElement('ul');for(const note of [...r.issues,...r.notes]){const li=document.createElement('li');li.textContent=explanations[note]||note;ul.append(li)}box.append(b,p,ul);parent.append(box)}
for(const id of ['basis','coverage','activity','metric'])document.getElementById(id).addEventListener('change',evidenceLab);evidenceLab();
const valueFields=['tasks','nativeMinutes','toolMinutes','hourlyValue','monthlyFee','monthlyQaCost','setupCost','amortisationMonths'];
function valueLab(){const x={currency:'ZAR'};for(const id of valueFields){const raw=document.getElementById(id).value;x[id]=raw.trim()===''?null:Number(raw)}const r=toolValue(x),parent=document.getElementById('valueOutput');parent.replaceChildren();const box=document.createElement('div');box.className='output'+(!r.valid?' fail':'');const b=document.createElement('b');b.textContent=r.valid?'Net planning value: '+new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR'}).format(r.netPlanningValue):'Incomplete or invalid assumptions';const p=document.createElement('p');p.textContent=r.valid?'Capacity value before fees and QA: '+new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR'}).format(r.capacityValue)+'. Not guaranteed cash savings.':'Complete every field with a non-negative number; amortisation months must be greater than zero. No stale result is retained.';box.append(b,p);parent.append(box)}
for(const id of valueFields)document.getElementById(id).addEventListener('input',valueLab);valueLab();
function filterSources(){const q=document.getElementById('sourceSearch').value.toLowerCase(),f=document.getElementById('sourceFilter').value;for(const card of document.querySelectorAll('.source'))card.hidden=!(card.textContent.toLowerCase().includes(q)&&(f==='all'||card.dataset.coverage===f))}document.getElementById('sourceSearch').addEventListener('input',filterSources);document.getElementById('sourceFilter').addEventListener('change',filterSources);
for(const button of document.querySelectorAll('[data-view]'))button.addEventListener('click',()=>{for(const view of document.querySelectorAll('.view'))view.hidden=view.id!=='view-'+button.dataset.view;for(const b of document.querySelectorAll('[data-view]'))b.setAttribute('aria-current',String(b===button));document.querySelector('.view:not([hidden])').scrollIntoView({block:'start',behavior:'smooth'})});
'''
nav=''.join('<button data-view="'+str(i+1)+'" aria-current="'+str(i==0).lower()+'">'+str(i+1).zfill(2)+' '+label+'</button>' for i,label in enumerate(labels))+'<button data-view="sources" aria-current="false">Source ledger</button>'
